"""Render a Briefing as Markdown — per-section functions for the UI tabs, plus the full download."""

import re

from core.citations import normalize_id
from core.schemas import Briefing, Reference

CITATION_IN_TEXT = re.compile(r"NCT\d{8}|PMID[:\s]*\d{5,9}|(?<=\[)FDA:[^\[\]]+(?=\])", re.IGNORECASE)

DISCLAIMER = (
    "_Research aid generated by an AI model from PubMed, openFDA and ClinicalTrials.gov. "
    "Not medical advice. Every citation links to its source; verify before use._"
)


def executive_md(b: Briefing) -> str:
    refs = _ref_index(b)
    lines = [b.executive.summary, "", "**Key points**"]
    lines += [f"- {_link_ids(p, refs)}" for p in b.executive.key_points] or ["- None"]
    lines += ["", "**Evidence gaps**"]
    lines += [f"- {g}" for g in b.executive.evidence_gaps] or ["- None noted"]
    return "\n".join(lines)


def standard_of_care_md(b: Briefing) -> str:
    refs = _ref_index(b)
    soc = b.standard_of_care
    lines = [
        "_Established care: sourced only from clinical guidelines, systematic reviews (PubMed) and FDA drug labels._",
        "",
        soc.summary or "_No standard-of-care evidence was available._",
        "",
    ]
    if soc.treatments:
        lines += ["| Treatment | Category | Role | Description | Sources |", "|---|---|---|---|---|"]
        lines += [
            f"| **{_cell(t.name)}** | {_cell(t.category)} | {_cell(t.role)} | {_cell(t.description)} | {_cite(t.citations, refs)} |"
            for t in soc.treatments
        ]
    return "\n".join(lines)


def emerging_md(b: Briefing) -> str:
    refs = _ref_index(b)
    em = b.emerging
    lines = [
        "_Investigational: sourced only from active trials on ClinicalTrials.gov. Not established care; efficacy is unproven until trials report._",
        "",
        em.summary or "_No emerging-treatment evidence was available._",
        "",
    ]
    if em.treatments:
        lines += ["### Treatments in development", "| Treatment | Regulatory status | Mechanism | Highest phase | Sponsor(s) | Potential impact | Trials |", "|---|---|---|---|---|---|---|"]
        lines += [
            f"| **{_cell(t.name)}** | {_regulatory_status(t.fda_labelled_agents)} | {_cell(t.mechanism or 'Not stated in sources')} | {t.highest_phase} "
            f"| {_cell(', '.join(t.sponsors))} | {_cell(t.potential_impact)} | {_cite(t.trial_ids, refs)} |"
            for t in em.treatments
        ]
        lines.append("")
    lines += trials_md(b)
    return "\n".join(lines)


def trials_md(b: Briefing) -> list[str]:
    trials = b.emerging.trials
    if not trials:
        return []
    lines = [f"### Active Phase 2/3 trials ({len(trials)} most recently updated)", "| Trial | Title | Phase | Status | Sponsor | Primary completion |", "|---|---|---|---|---|---|"]
    lines += [
        f"| [{t.nct_id}]({t.url}) | {_cell(t.title)} | {_cell(', '.join(p.replace('PHASE', 'Phase ') for p in t.phases))} "
        f"| {t.status.replace('_', ' ').title()} | {_cell(t.sponsor)} | {t.primary_completion or '—'} |"
        for t in trials
    ]
    return lines


def landscape_md(b: Briefing) -> str:
    ls = b.landscape
    lines = [ls.summary or "_No trial sponsor data was found._", ""]
    if ls.organizations:
        lines += ["| Organization | Type | Active trials | As lead sponsor | Example interventions |", "|---|---|---|---|---|"]
        lines += [
            f"| {_cell(o.name)} | {o.kind} | {len(o.trial_ids)} | {o.lead_sponsor_count} | {_cell(', '.join(o.interventions)) or '—'} |"
            for o in ls.organizations
        ]
        lines += ["", "_Counts are based on the most recently updated active interventional trials on ClinicalTrials.gov._"]
    return "\n".join(lines)


def references_md(b: Briefing) -> str:
    if not b.references:
        return "_No sources were cited._"
    return "\n".join(f"- **{r.id}** — [{_cell(r.title)}]({r.url}) · {r.source}" for r in b.references)


def warnings_md(b: Briefing) -> str:
    return "\n".join(f"- {w}" for w in b.warnings)


def failures_md(b: Briefing) -> str:
    return "\n".join(f"- {f}" for f in b.source_failures)


def to_markdown(b: Briefing) -> str:
    parts = [
        f"# Research Briefing: {b.condition}",
        f"Query: _{b.query}_ · Generated {b.generated_at}",
        DISCLAIMER,
        "## Executive summary", executive_md(b),
        "## Current standard of care", standard_of_care_md(b),
        "## Emerging treatments and trials", emerging_md(b),
        "## Companies and research institutions", landscape_md(b),
        "## References", references_md(b),
    ]
    if b.source_failures:
        parts.insert(3, "**⚠️ Partial briefing: some sources could not be reached.**\n\n" + failures_md(b))
    if b.warnings:
        parts += ["## Data quality notes", warnings_md(b)]
    return "\n\n".join(parts)


def _ref_index(b: Briefing) -> dict[str, Reference]:
    return {r.id: r for r in b.references}


def _cite(ids: list[str], refs: dict[str, Reference]) -> str:
    return ", ".join(f"[{i}]({refs[i].url})" if i in refs else i for i in ids)


def _link_ids(text: str, refs: dict[str, Reference]) -> str:
    def link(match: re.Match) -> str:
        ref_id = normalize_id(match.group(0))
        return f"[{ref_id}]({refs[ref_id].url})" if ref_id in refs else match.group(0)

    return CITATION_IN_TEXT.sub(link, text)


def _regulatory_status(fda_labelled_agents: list[str]) -> str:
    if not fda_labelled_agents:
        return "Investigational"
    return f"New use/combination of FDA-labelled {', '.join(a.title() for a in fda_labelled_agents)}"


def _cell(text: str) -> str:
    """Make text safe inside a Markdown table cell."""
    return text.replace("|", "\\|").replace("\n", " ").strip()
